pick({ a: 1, b: 2, c: 3 }, ['a', 'c']); // {a:1,c:3}
omit({ a: 1, b: 2, c: 3 }, ['b']); // {a:1,c:3}
```

`hasOwnProperty` avoids copying inherited enumerable keys. Values are shallow-copied.

```javascript
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function withTimeout(promise, ms, message = 'timeout') {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(message)), ms);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}
```

Clearing the timer in `finally` avoids keeping the event loop alive after the real promise wins. `sleep` is the usual delay helper for tests and retries.

```javascript
function* range(start, end, step = 1) {
  if (step === 0) throw new Error('step cannot be 0');
  if (step > 0) {
    for (let i = start; i < end; i += step) yield i;
  } else {
    for (let i = start; i > end; i += step) yield i;
  }
}

[...range(0, 5)]; // [0,1,2,3,4]
[...range(5, 0, -2)]; // [5,3,1]
```

Exclusive end matches Python. The comparison depends on the sign of step so a mismatched sign yields nothing instead of looping forever.

```javascript
function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

isPlainObject({}); // true
isPlainObject(Object.create(null)); // true
isPlainObject([]); // false
isPlainObject(new Date()); // false
```

Arrays, dates, and class instances have other prototypes. This is the usual guard before a recursive merge.

```javascript
function deepEqual(a, b) {
  if (Object.is(a, b)) return true;
  if (typeof a !== typeof b) return false;
  if (a == null || b == null) return false;
  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((v, i) => deepEqual(v, b[i]));
  }
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  if (typeof a === 'object') {
    const ak = Object.keys(a), bk = Object.keys(b);
    if (ak.length !== bk.length) return false;
    return ak.every((k) => Object.prototype.hasOwnProperty.call(b, k) && deepEqual(a[k], b[k]));
  }
  return false;
}
```

`Object.is` handles `NaN` and distinguishes `-0`. This is not a general value equality for Dates or Maps.

```javascript
function jwtPayload(token) {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('invalid token');
  const b64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');
  const padded = b64 + '='.repeat((4 - (b64.length % 4)) % 4);
  const json = Buffer.from(padded, 'base64').toString('utf8');
  return JSON.parse(json);
}
```

This only decodes. Never trust claims from an unverified JWT. In browsers, replace `Buffer` with `atob` plus `decodeURIComponent` for Unicode.

```javascript
function joinUrl(...parts) {
  const cleaned = parts
    .filter((p) => p != null && p !== '')
    .map((p, i) => {
      const s = String(p);
      if (i === 0) return s.replace(/\/+$/, '');
      return s.replace(/^\/+/, '').replace(/\/+$/, '');
    })
    .filter(Boolean);
  const joined = cleaned.join('/');
  return parts[0] && String(parts[0]).startsWith('/') ? (joined.startsWith('/') ? joined : '/' + joined) : joined;
}

joinUrl('/api/', '/v1/', 'users/'); // '/api/v1/users'
```

This is path joining only, not a full URL resolver. Query strings should be appended after joining.

```javascript
function slugify(title) {
  return String(title)
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

slugify('Hello, World!'); // 'hello-world'
slugify('  Café déjà vu  '); // 'cafe-deja-vu'
```

NFKD plus stripping combining marks turns é into e. Empty titles become `''`.

```javascript
function truncate(text, maxLen) {
  if (text.length <= maxLen) return text;
  if (maxLen <= 1) return '…'.slice(0, maxLen);
  const budget = maxLen - 1;
  let cut = text.slice(0, budget);
  const space = cut.lastIndexOf(' ');
  if (space > 0) cut = cut.slice(0, space);
  return cut.replace(/\s+$/, '') + '…';
}

truncate('hello world friends', 12); // 'hello world…' or similar within 12
```

The function always returns a string of length <= maxLen. Very small budgets fall back to just the ellipsis.

```javascript
function titleCase(text) {
  return text.replace(/\S+/g, (word) => word.charAt(0).toUpperCase() + word.slice(1));
}

titleCase('hello from the ops team'); // 'Hello From The Ops Team'
```

This does not implement publishing title rules (small words stay capitalized). Use a word list if you need Chicago-style exceptions.

```javascript
function filterObject(obj, pred) {
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    if (pred(k, v)) out[k] = v;
  }
  return out;
}

filterObject({ a: 1, b: 0, c: 3 }, (_k, v) => v > 0); // {a:1,c:3}
```

`Object.entries` skips symbols and inherited keys. The original object is not mutated.

