A shorter variant: `find . -type f -printf '%f\n' | awk -F. '{print (NF>1?$NF:"(none)")}' | sort | uniq -c | sort -nr`. Hidden files like `.env` are treated as extension `env` by the short form; adjust if you want `(none)`.

```bash
# usage: set -a; source ./load_env.sh; set +a   if you want export
while IFS= read -r line || [ -n "$line" ]; do
  case "$line" in
    ''|\#*) continue ;;
  esac
  key=${line%%=*}
  val=${line#*=}
  val=${val%$\r}
  printf -v "$key" '%s' "$val"
done < .env
